// src/components/DeliveryTracking.tsx

import React, { useEffect, useState, useRef } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";
import io from "socket.io-client";
import {
  GoogleMap,
  Marker,
  DirectionsRenderer,
  Polyline,
  useJsApiLoader
} from "@react-google-maps/api";

const API_BASE_URL        = process.env.REACT_APP_API_URL || "http://localhost:5000";
const SOCKET_URL         = process.env.REACT_APP_API_URL || "http://localhost:5000";
const GOOGLE_MAPS_API_KEY= process.env.REACT_APP_GOOGLE_MAPS_API_KEY || "";

const containerStyle = { width: "100%", height: "600px" };
const defaultCenter   = { lat: 6.9271, lng: 79.8612 };

export default function DeliveryTracking() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const mapRef = useRef<google.maps.Map|null>(null);

  // Addresses & coords
  const [driverAddress, setDriverAddress]       = useState("");
  const [deliveryAddress, setDeliveryAddress]   = useState("");
  const [driverLocation, setDriverLocation]     = useState<google.maps.LatLngLiteral|null>(null);
  const [destination, setDestination]           = useState<google.maps.LatLngLiteral|null>(null);

  // Planned route & live path
  const [directions, setDirections]             = useState<google.maps.DirectionsResult|null>(null);
  const [routeCoordinates, setRouteCoordinates] = useState<google.maps.LatLngLiteral[]>([]);

  // Load Maps JS API
  const { isLoaded, loadError } = useJsApiLoader({
    googleMapsApiKey: GOOGLE_MAPS_API_KEY,
    libraries: ["places"]
  });

  // 1️⃣ Fetch delivery + driver, geocode driver address
  useEffect(() => {
    if (!id) return;
    (async () => {
      try {
        // Delivery data
        const { data: delivery } = await axios.get(`${API_BASE_URL}/api/delivery/${id}`);
        setDeliveryAddress(delivery.address);
        setDestination(delivery.location);

        // Driver data
        const { data: driver } = await axios.get(`${API_BASE_URL}/api/drivers/${delivery.driverId}`);
        setDriverAddress(driver.address);

        // Geocode driver address
        const { data: geo } = await axios.get(
          `https://maps.googleapis.com/maps/api/geocode/json`,
          { params: { address: driver.address, key: GOOGLE_MAPS_API_KEY } }
        );
        const loc = geo.results[0].geometry.location;
        setDriverLocation({ lat: loc.lat, lng: loc.lng });
        // Start the live path
        setRouteCoordinates([{ lat: loc.lat, lng: loc.lng }]);
      } catch (err) {
        console.error("Fetch error:", err);
      }
    })();
  }, [id]);

  // 2️⃣ Compute the planned route
  useEffect(() => {
    if (!isLoaded || !driverLocation || !destination) return;

    const svc = new google.maps.DirectionsService();
    svc.route(
      {
        origin: driverLocation,
        destination,
        travelMode: google.maps.TravelMode.DRIVING
      },
      (res, status) => {
        if (status === "OK" && res) {
          setDirections(res);
          mapRef.current?.fitBounds(res.routes[0].bounds);
        } else {
          console.error("Directions failed:", status);
        }
      }
    );
  }, [isLoaded, driverLocation, destination]);

  // 3️⃣ Open socket, join room, and listen for live driver updates
  useEffect(() => {
    if (!id) return;
    const socket = io(SOCKET_URL);

    // Join this delivery’s room
    socket.emit("trackDelivery", id);

    // ← Here’s the handler you asked to add:
    socket.on("driverLocationUpdate", (loc: { lat: number; lng: number }) => {
      // 1. Move marker
      setDriverLocation(loc);
      // 2. Append to live route polyline
      setRouteCoordinates(path => [...path, loc]);
    });

    return () => {
      socket.off("driverLocationUpdate");
      socket.disconnect();
    };
  }, [id]);

  if (loadError) return <div>Error loading maps</div>;
  if (!isLoaded) return <div>Loading map…</div>;

  return (
    <div style={{ padding: 20 }}>
      <button
        onClick={() => navigate(-1)}
        style={{
          marginBottom: 10, padding: "8px 16px",
          background: "#6c757d", color: "#fff",
          border: "none", borderRadius: 4, cursor: "pointer"
        }}
      >
        ← Back
      </button>

      <div style={{ marginBottom: 16 }}>
        <p><strong>Driver Addr:</strong> {driverAddress}</p>
        <p><strong>Delivery Addr:</strong> {deliveryAddress}</p>
      </div>

      <GoogleMap
        mapContainerStyle={containerStyle}
        center={driverLocation || destination || defaultCenter}
        zoom={12}
        onLoad={map => { mapRef.current = map!; }}
      >
        {/* Current driver marker */}
        {driverLocation && <Marker position={driverLocation} label="🚚" />}

        {/* Delivery marker */}
        {destination && <Marker position={destination} label="📍" />}

        {/* Planned static route */}
        {directions && (
          <DirectionsRenderer
            directions={directions}
            options={{
              suppressMarkers: true,
              polylineOptions: {
                strokeColor: "#1E90FF",
                strokeOpacity: 0.6,
                strokeWeight: 4
              }
            }}
          />
        )}

        {/* Live traveled path */}
        {routeCoordinates.length > 1 && (
          <Polyline
            path={routeCoordinates}
            options={{
              strokeColor: "#FF6347",
              strokeOpacity: 0.8,
              strokeWeight: 4,
              icons: [{
                icon: { path: google.maps.SymbolPath.FORWARD_CLOSED_ARROW },
                offset: "100%"
              }]
            }}
          />
        )}
      </GoogleMap>
    </div>
  );
}
